import { Component, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatRippleModule } from '@angular/material/core';
import {
    MAT_DIALOG_DATA,
    MatDialogModule,
    MatDialogRef,
} from '@angular/material/dialog';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import {
    OrganisationService,
    SettingsService,
    i18n,
    notifyError,
    notifySuccess,
} from '@placeos/common';
import {
    IconComponent,
    SettingsToggleComponent,
    TranslatePipe,
} from '@placeos/components';
import { showMetadata, updateMetadata } from '@placeos/ts-client';
import { errorText } from '../ui/modal-actions';

@Component({
    selector: 'induction-settings-modal',
    template: `
        <header
            class="bg-base-200 m-2 flex h-14 w-[calc(100%-1rem)] items-center justify-between rounded-sm border-none px-4 py-2"
        >
            <h3 class="text-xl font-medium">
                {{ 'APP.CONCIERGE.INDUCTION_HEADER' | translate }}
            </h3>
            @if (!loading()) {
                <button icon matRipple mat-dialog-close>
                    <icon class="text-2xl">close</icon>
                </button>
            }
        </header>
        @if (!loading()) {
            <main class="flex flex-col space-y-2 px-4">
                <settings-toggle
                    [(ngModel)]="is_enabled"
                    [label]="'APP.CONCIERGE.INDUCTION_ENABLE' | translate"
                ></settings-toggle>
                <mat-form-field
                    appearance="outline"
                    class="h-[50vh] w-xl max-w-[80vw]"
                >
                    <textarea
                        matInput
                        [(ngModel)]="induction_details"
                        [placeholder]="
                            'APP.CONCIERGE.INDUCTION_DETAILS' | translate
                        "
                        class="h-[calc(50vh-2rem)] w-136 max-w-[calc(80vw-2rem)] resize-none"
                    ></textarea>
                </mat-form-field>
            </main>
        } @else {
            <main
                class="flex flex-col items-center justify-center space-y-2 p-32"
            >
                <mat-spinner [diameter]="48"></mat-spinner>
                <p>{{ loading() }}</p>
            </main>
        }
        @if (!loading()) {
            <footer
                class="border-base-200 mt-2 flex justify-end border-t px-4 py-2"
            >
                <button btn matRipple class="w-32" (click)="save()">
                    Save
                </button>
            </footer>
        }
    `,
    styles: [``],
    imports: [
        MatDialogModule,
        IconComponent,
        TranslatePipe,
        MatRippleModule,
        MatProgressSpinnerModule,
        MatFormFieldModule,
        MatInputModule,
        SettingsToggleComponent,
        FormsModule,
    ],
})
export class InductionSettingsModalComponent implements OnInit {
    private _zone_id = inject(MAT_DIALOG_DATA);
    private _settings = inject(SettingsService);
    private _org = inject(OrganisationService);
    private _dialog_ref =
        inject<MatDialogRef<InductionSettingsModalComponent>>(MatDialogRef);

    public readonly loading = signal('');
    public readonly induction_details = signal('');
    public readonly is_enabled = signal(false);
    public readonly settings = signal<Record<string, any>>({});

    public ngOnInit() {
        if (!this._zone_id) return;
        this.loadSettings();
    }

    public async loadSettings() {
        this.loading.set(i18n('APP.CONCIERGE.INDUCTION_LOADING'));
        const visitor_kiosk_app =
            this._settings.get('app.visitor_kiosk_metadata_key') ||
            this._settings.get('app.visitor_kiosk_app') ||
            'visitor-kiosk_app';
        try {
            const [bld_metadata, org_metadata, org_settings] =
                await Promise.all([
                    showMetadata(this._zone_id, visitor_kiosk_app),
                    showMetadata(this._org.organisation.id, visitor_kiosk_app),
                    showMetadata(this._org.organisation.id, 'settings'),
                ]);
            const settings: Record<string, any> = {
                ...org_settings.details,
                ...org_metadata.details,
                ...bld_metadata.details,
            };
            this.settings.set(settings);
            this.induction_details.set(settings.induction_details || '');
            this.is_enabled.set(settings.induction_enabled ?? false);
        } catch (e) {
            // Saving defaults over settings that failed to load would lose
            // them, so close instead.
            notifyError(`Failed to load induction settings. ${errorText(e)}`);
            this._dialog_ref.close();
        } finally {
            this.loading.set('');
        }
    }

    public async save() {
        this.loading.set(i18n('APP.CONCIERGE.INDUCTION_SAVING'));
        const visitor_kiosk_app =
            this._settings.get('app.visitor_kiosk_metadata_key') ||
            this._settings.get('app.visitor_kiosk_app') ||
            'visitor-kiosk_app';
        const concierge_app =
            this._settings.get('app.concierge_metadata_key') ||
            this._settings.get('app.concierge_app') ||
            'concierge_app';
        const induction = {
            induction_details: this.induction_details(),
            induction_enabled: this.is_enabled(),
        };
        this._dialog_ref.disableClose = true;
        try {
            // Both apps read the induction settings, so both must be saved.
            for (const key of [visitor_kiosk_app, concierge_app]) {
                const metadata = await showMetadata(this._zone_id, key);
                await updateMetadata(this._zone_id, {
                    name: metadata.name || key,
                    description: metadata.description || '',
                    details: { ...metadata.details, ...induction },
                });
            }
            notifySuccess(i18n('APP.CONCIERGE.INDUCTION_SUCCESS'));
            this._dialog_ref.close();
        } catch (e) {
            notifyError(
                i18n('APP.CONCIERGE.INDUCTION_ERROR', { error: errorText(e) }),
            );
        } finally {
            this._dialog_ref.disableClose = false;
            this.loading.set('');
        }
    }
}
